| CREATE POLICY "誰でも読める（期限内・パブリックのみ）" ON "public"."letters" FOR SELECT TO public USING (((is_private = false) AND ((expires_at IS NULL) OR (expires_at > now()))));                                                                                                                           |
| CREATE POLICY "ログインユーザーは投稿できる" ON "public"."letters" FOR INSERT TO authenticated WITH CHECK ((auth.uid() = user_id));                                                                                                                                                                       |
| CREATE POLICY "Users can select their own favorites" ON "public"."favorites" FOR SELECT TO public USING ((auth.uid() = user_id));                                                                                                                                                           |
| CREATE POLICY "Users can insert their own favorites" ON "public"."favorites" FOR INSERT TO public WITH CHECK ((auth.uid() = user_id));                                                                                                                                                      |
| CREATE POLICY "Users can delete their own favorites" ON "public"."favorites" FOR DELETE TO public USING ((auth.uid() = user_id));                                                                                                                                                           |
| CREATE POLICY "Profiles are viewable by everyone" ON "public"."profiles" FOR SELECT TO public USING (true);                                                                                                                                                                                 |
| CREATE POLICY "Users can insert their own profile" ON "public"."profiles" FOR INSERT TO public WITH CHECK ((auth.uid() = id));                                                                                                                                                              |
| CREATE POLICY "Users can view their own stamps" ON "public"."user_stamps" FOR SELECT TO public USING ((auth.uid() = user_id));                                                                                                                                                              |
| CREATE POLICY "Users can insert their own stamps" ON "public"."user_stamps" FOR INSERT TO public WITH CHECK ((auth.uid() = user_id));                                                                                                                                                       |
| CREATE POLICY "Enable read access for all users" ON "public"."stamps" FOR SELECT TO public USING (true);                                                                                                                                                                                    |
| CREATE POLICY "Admins can do everything" ON "public"."profiles" FOR ALL TO public USING ((is_admin = true));                                                                                                                                                                                |
| CREATE POLICY "Anyone can insert reports" ON "public"."reports" FOR INSERT TO public WITH CHECK (true);                                                                                                                                                                                     |
| CREATE POLICY "Admins can view reports" ON "public"."reports" FOR SELECT TO public USING ((( SELECT profiles.is_admin
   FROM profiles
  WHERE (profiles.id = auth.uid())) = true));                                                                                                        |
| CREATE POLICY "Admins can view all letters" ON "public"."letters" FOR SELECT TO public USING ((( SELECT profiles.is_admin
   FROM profiles
  WHERE (profiles.id = auth.uid())) = true));                                                                                                    |
| CREATE POLICY "Users can manage their own stamps" ON "public"."user_stamps" FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));                                                                                                                    |
