| CREATE POLICY "管理者はすべての手紙を削除できる" ON "public"."letters" FOR DELETE TO public USING ((auth.email() = ANY (ARRAY['marei.suyama@gmail.com'::text, 'contact@volvox-ltd.com'::text])));                                                                                                           |
| CREATE POLICY "管理者はすべての手紙を編集できる" ON "public"."letters" FOR UPDATE TO public USING ((auth.email() = ANY (ARRAY['marei.suyama@gmail.com'::text, 'contact@volvox-ltd.com'::text]))) WITH CHECK ((auth.email() = ANY (ARRAY['marei.suyama@gmail.com'::text, 'contact@volvox-ltd.com'::text]))); |
