| CREATE POLICY "Admin full access" ON "public"."letters" FOR INSERT TO authenticated WITH CHECK (((auth.jwt() ->> 'email'::text) = ANY (ARRAY['marei.suyama@gmail.com'::text, 'contact@volvox-ltd.com'::text])));                                                                            |
